(function(){
function mediaOk(u){if(typeof u!='string'||u.indexOf('http')!=0)return '';if(u.indexOf('.m3u8')>=0||u.indexOf('.mp4')>=0||u.indexOf('.flv')>=0)return u;return '';}
function urlOk(u){if(typeof u!='string')return '';if(u.indexOf('https://')==0||u.indexOf('http://')==0)return u;return '';}
function decryptOk(u){var r=urlOk(u);if(!r)return '';if(r.indexOf('.html')>0||r.indexOf('.php')>0||r.indexOf('.shtm')>0)return '';try{if(location.origin&&r.indexOf(location.origin)===0)return '';}catch(e){}return r;}
function perfM3u8(){try{var es=performance.getEntriesByType('resource');for(var i=es.length-1;i>=0;i--){var n=es[i].name;if(n&&n.indexOf('http')==0&&n.indexOf('.m3u8')>=0)return n;}}catch(e){}return '';}
function artTry(){try{
var A=window.Artplayer||window.ArtPlayer;
if(A&&A.instances&&A.instances.length){
for(var i=0;i<A.instances.length;i++){
var a=A.instances[i];
var u1=(a&&a.option&&typeof a.option.url=='string')?a.option.url:'';
var u2=(a&&a.hls&&typeof a.hls.url=='string')?a.hls.url:'';
var r=urlOk(u1)||urlOk(u2);
if(r)return r;
}}
}catch(e){}return '';}
function syncTry(){var f=document.querySelector('iframe#video');var r=mediaOk(f&&f.getAttribute('src'));if(!r){var v=document.querySelector('#artplayer video, video');if(v){r=urlOk(v.currentSrc||v.src);}}if(!r){r=artTry();}if(!r){r=perfM3u8();}return r;}
function wrapHxm(){
try{
if(window.hxm_decrypt&&!window.__animeHxm){
window.__animeHxm=1;
var od=window.hxm_decrypt;
window.hxm_decrypt=function(x){
var res=od(x);
try{var d=res;try{d=decodeURIComponent(String(res));}catch(e2){}var m=decryptOk(d)||decryptOk(String(res))||mediaOk(String(res));if(m)post(m);}catch(e){}
return res;
};
return true;
}
}catch(e){}
return false;
}
function post(u){try{window.animeBridge.onLink(u);}catch(e){}}
var R=syncTry();
if(R){return R;}
if(!window.__animeHook){
window.__animeHook=1;
try{var oo=XMLHttpRequest.prototype.open;XMLHttpRequest.prototype.open=function(m,u){try{var s=String(u);if(s.indexOf('http')==0&&s.indexOf('.m3u8')>=0){post(s);}}catch(e){}return oo.apply(this,arguments);};}catch(e){}
try{var of=window.fetch;window.fetch=function(){try{var a=arguments[0];var s=(typeof a=='string')?a:((a&&a.url)||'');if(s&&s.indexOf('http')==0&&s.indexOf('.m3u8')>=0){post(s);}}catch(e){}return of.apply(this,arguments);};}catch(e){}
if(!wrapHxm()){var hv=setInterval(function(){if(wrapHxm()){clearInterval(hv);}},400);setTimeout(function(){clearInterval(hv);},15000);}
setTimeout(function(){
try{
if(window.__animeRedrive)return;
