if(A&&A.instances&&A.instances.length)return;
if(document.querySelector('iframe#video'))return;
if(document.querySelector('#error'))return;
if(typeof window.hxm_encrypt=='function'&&typeof window.ajax_api=='function'){
window.__animeRedrive=1;
window.ajax_api();
}
}catch(e){}
},8000);
